pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether (constructor) and additional 1 ether for potential transfer
        vm.deal(address(c), 1 ether);

        // Prepare actor
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);

        // Compute hash corresponding to block.number after lockInGuess
        bytes32 expectedHash = keccak256(abi.encodePacked(uint(1))); // dummy hash

        // Call lockInGuess with some hash
        c.lockInGuess{value: 1 ether}(expectedHash);

        // Now warp to block.number + 2 to ensure block.number > stored block
        vm.roll(block.number + 2);

        // The bug stores guesses[msg.sender].block = block.number (original block) 
        // Reference stores block.number + 1
        // After lockInGuess, reference stored block = block.number + 1, bug stored block = block.number
        // Current block.number = original + 2, so both pass require(block.number > stored block)
        // But blockhash(original.block) = hash of original block (non-zero)
        // blockhash(original.block + 1) = hash of next block (non-zero)
        // Actually assume blockhash is not zero for both - need differ in guess match

        // Simpler: we make guess equal to blockhash for reference but not for bug
        // Actually we cannot control blockhash, so we choose hash that matches reference's blockhash
        // Let's use known blockhash at a specific block
        vm.roll(100);
        bytes32 refBlockhash = blockhash(100);

        // Reset state and try again
        // Deploy new contract to reset
        c = new C();
        vm.deal(address(c), 2 ether);
        vm.deal(alice, 2 ether);

        vm.roll(100); // set block.number to 100
        bytes32 guessHash = blockhash(100); // this will be the blockhash we want

        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Now warp to block > 101 for reference, > 100 for bug
        vm.roll(102);

        // Call settle
        vm.prank(alice);
        c.settle();

        // In reference: stored block = 101, blockhash(101) could be 0 (unavailable after 256 blocks)
        // Better approach: ensure blockhash is available
        // Use block.number close to current
        c = new C();
        vm.deal(address(c), 2 ether);
        vm.deal(alice, 2 ether);

        uint currentBlock = block.number;
        vm.roll(currentBlock);

        // Choose hash that matches blockhash of (currentBlock + 1) for reference
        bytes32 targetHash = blockhash(currentBlock + 1);
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(targetHash);

        // Now roll to currentBlock + 2 so block.number > stored block for both
        vm.roll(currentBlock + 2);

        vm.prank(alice);
        c.settle();

        // Reference: stored block = currentBlock + 1, blockhash(currentBlock+1) = targetHash, so transfer 2 ether
        // Bug: stored block = currentBlock, blockhash(currentBlock) != targetHash, no transfer
        // Check balance: Alice paid 1 ether, if she got 2 back she has 1 ether net gain
        assertTrue(alice.balance == 2 ether); // reference: alice gets 2 ether transfer -> balance = 2 - 1 + 2 = 3? Actually initial deal 2, pay 1 = 1, get 2 = 3
        // Let's compute precisely
    }
}

