        vm.deal(alice, 1 ether);
        vm.deal(address(c), 1 ether);

        // lockInGuess with 1 ether and hash = 0x0
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(bytes32(0x0));

        // move to block where blockhash is non-zero (e.g., block 3)
        vm.roll(3);

        // settle: blockhash(2) is non-zero (default forge blockhash is keccak256 of block number)
        // reference: answer != 0 (true) && guess == answer (false, since guess is 0 and answer is non-zero) => no transfer
        // bug: answer == 0 (false) && guess == answer (false) => no transfer
        // Actually need blockhash=0 to differentiate: on block 0, blockhash(0) is 0 in EVM
        // Let's use block number 1 for lockInGuess, so blockhash(2) is non-zero? Simpler: warp to block where blockhash is 0
        vm.roll(1);
        c.settle();

        // After settle, reference: no transfer, balance unchanged
        // Bug: condition answer == 0 (false) && guess == answer (false) => no transfer
        // Actually both do nothing. Need a scenario where reference pays but bug doesn't:
        // If answer is 0 and guess is 0x0, reference: answer != 0 is false, so no pay. Bug: answer == 0 is true && guess == answer is true => pay
        // Reset:
        c = new C();
        vm.deal(alice, 1 ether);
        vm.deal(address(c), 1 ether);

        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(bytes32(0x0));

        // LockInGuess sets block to block.number+1 = current block+1
        // We need blockhash(thatblock) == 0. In Foundry, blockhash of any block > block.number is 0.
        // If we lock at block 1, block stored = 2. Then if we settle at block 3, blockhash(2) is non-zero.
        // To get blockhash=0, we need to request blockhash of a block that's >= block.number or non-existent.
        // Actually blockhash(block.number - 1) is valid. Let's lock at block 1 (stored 2), then settle at block 2: blockhash(2) is 0 because it's >= block.number?
        // No, blockhash(2) when block.number=2 is 0. So:
        vm.roll(2);
        c.settle();

        // Now check balance of alice
        // Reference: no transfer, alice still has 0 (she spent 1 ether, got nothing)
        // Bug: transfer 2 ether, alice has 2 ether
        assertEq(alice.balance, 2 ether);
    }
}

