    function testRegression_property() public {
        // lock in guess on block 1
        vm.roll(1);
        bytes32 guessHash = blockhash(1);
        c.lockInGuess{value: 1 ether}(guessHash);

        // attempt to settle on the same block (block 1)
        // Reference should revert; buggy version should succeed
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference passes (ok == false), buggy version fails (ok == true)
        assertTrue(ok == false);
    }
}
